const initialState = {
    dogs: [],
    allDogs: [],
    temperaments: [],
    details: [],
    orderByName: null,
    orderByWeight: null,
  };
  
  
  function dogReducer(state = initialState, action) {
    switch (action.type) {
      case "ORDER_BY_TEMPERAMENT":
        const allDogs = state.allDogs;
        const statusFiltered =
          action.payload === "All"
            ? allDogs
            : allDogs.filter((el) => el.types.map(typ => typ.name).includes(action.payload));
  
        return {
          ...state,
          dogs: statusFiltered 
        };
      //Its working
      case "GET_NAME":
        return {
          ...state,
          dogs: action.payload,
        };
  
        case "GET_TEMPERAMENT": 
        return {
          ...state,
          types: action.payload,
        }
      //check this later too
      case "GET_ID":
        return {
          ...state,
          // iba a ponerle id pero por las dudas algo ya se llame id y crashee
          details: action.payload,
        };
      //check this as well
      case "POST_DOG":
        return {
          ...state,
        };
      //check this
      case "FILTER_DB":
         const allDogRevenge = state.allDogs;
        /*  console.log(action.payload); */
        const filter2 =
          action.payload === "Created"
            ? allDogRevenge.filter((ele) => ele.createdInDb)
            : allDogRevenge.filter((ele) => !ele.createdInDb);
        return {
          ...state,
          dogs:
            action.payload === "All"
              ? allDogRevenge
              : filter2.length
              ? filter2
              : [],
        }; 
       
        case "RESTORE_DOG":
          return{
              ...state,
              details: []
          }
      case "GET_DOG":
                    
        return {
          ...state,
          dogs: action.payload,
          allDogs: action.payload,
        };
      case "ORDER_BY_NAME_ASC":
        const dogsByNameAsc = state.dogs.slice().sort((a, b) => a.name.localeCompare(b.name));
        return {
          ...state,
          dogs: dogsByNameAsc,
         };
      case "ORDER_BY_NAME_DESC":
            const dogsByNameDesc = state.dogs.slice().sort((a, b) => b.name.localeCompare(a.name));
            return {
              ...state,
              dogs: dogsByNameDesc,
             };
      case "ORDER_BY_WEIGHT_ASC":
            const dogsByWeightAsc = state.dogs.slice().sort((a, b) => a.weight - b.weight);
            return {
              ...state,
              dogs: dogsByWeightAsc,
             };
      case "ORDER_BY_WEIGHT_DESC":
             const dogsByWeightDesc = state.dogs.slice().sort((a, b) => b.weight - a.weight);
             return {
                  ...state,
               dogs: dogsByWeightDesc,
             };
         default:
        return state;
    }
  }
  export default dogReducer;
